160	string ZipEntry::readAsText(ZipArchive::State state, libzippp_uint64 size) const {
161	    char* content = (char*)zipFile->readEntry(*this, true, state, size);
162	    if (content==nullptr) { return string(); } //happen if the ZipArchive has been closed or the entry does not exist in the state
163	
164	    //the read length is computed from the entry AS IT IS IN THE REQUESTED STATE instead of
165	    //from the size captured when this object was obtained: a replacement may be longer,
166	    //shorter or empty and the object is not required to be fetched again to read it
167	    libzippp_uint64 maxSize = zipFile->getEntry((libzippp_int64)index, state).getSize();
168	    libzippp_uint64 length = size==0 || size>maxSize ? maxSize : size;
169	    string str(content, length); //the extra '\0' appended by readEntry is not part of the content
170	    delete[] content;
171	    return str;
172	}
