178	basic_string<libzippp_uint8> ZipEntry::readAsBinaryString(ZipArchive::State state, libzippp_uint64 size) const {
179	    libzippp_uint8* content = (libzippp_uint8*)zipFile->readEntry(*this, true, state, size);
180	    if (content==nullptr) { return basic_string<libzippp_uint8>(); } //happen if the ZipArchive has been closed or the entry does not exist in the state
181	
182	    //see readAsText: the length must reflect the requested state (zero bytes inside the
183	    //content are preserved, the extra '\0' is only an allocation artifact)
184	    libzippp_uint64 maxSize = zipFile->getEntry((libzippp_int64)index, state).getSize();
185	    libzippp_uint64 length = size==0 || size>maxSize ? maxSize : size;
186	    basic_string<libzippp_uint8> str(content, length);
187	    delete[] content;
188	    return str;
189	}
