267	bool ZipArchive::openBuffer(void** data, libzippp_uint32 size, OpenMode om, bool checkConsistency) {
268	    zip_error_t error;
269	    zip_error_init(&error);
270	
271	    /* create source from buffer */
272	    zip_source* localZipSource = zip_source_buffer_create(*data, size, 0, &error);
273	    if (localZipSource == nullptr) {
274	        Helper::callErrorHandlingCallback(&error, "can't create zip source: %s\n", errorHandlingCallback);
275	        zip_error_fini(&error);
276	        return false;
277	    }
278	
279	    bool open = openSource(localZipSource, om, checkConsistency);
280	    if (open) {
281	        if (om==Write || om==New) {
282	            bufferData = data;
283	            bufferLength = size;
284	
285	            //prevents libzip to delete the source when closing the ZipArchive
286	            zip_source_keep(localZipSource);
287	        }
288	    } else {
289	        zip_source_free(localZipSource);
290	        localZipSource = nullptr;
291	    }
292	    return open;
293	}
