295	bool ZipArchive::openSource(zip_source* source, OpenMode om, bool checkConsistency) {
296	    int zipFlag = 0;
297	    if (om == ReadOnly) { zipFlag = 0; }
298	    else if (om == Write) { zipFlag = ZIP_CREATE; }
299	    else if (om == New) { zipFlag = ZIP_CREATE | ZIP_TRUNCATE; }
300	    else { return false; }
301	    if (checkConsistency) {
302	        zipFlag = zipFlag | ZIP_CHECKCONS;
303	    }
304	
305	    zip_error_t error;
306	    zip_error_init(&error);
307	
308	    /* open zip archive from source */
309	    zipHandle = zip_open_from_source(source, zipFlag, &error);
310	    if (zipHandle == nullptr) {
311	        Helper::callErrorHandlingCallback(&error, "can't open zip from source: %s\n", errorHandlingCallback);
312	        zip_error_fini(&error);
313	        return false;
314	    }
315	    zip_error_fini(&error);
316	
317	    zipSource = source;
318	
319	#ifdef LIBZIPPP_WITH_ENCRYPTION
320	    if (isEncrypted()) {
321	        int result = zip_set_default_password(zipHandle, password.c_str());
322	        if (result != 0) {
323	            close();
324	            return false;
325	        }
326	    }
327	#endif
328	
329	    mode = om;
330	    return true;
331	}
