333	bool ZipArchive::open(OpenMode om, bool checkConsistency) {
334	    if (isOpen()) { return om==mode; }
335	
336	    int zipFlag = 0;
337	    if (om==ReadOnly) { zipFlag = 0; }
338	    else if (om==Write) { zipFlag = ZIP_CREATE; }
339	    else if (om==New) { zipFlag = ZIP_CREATE | ZIP_TRUNCATE; }
340	    else { return false; }
341	
342	    if (checkConsistency) {
343	        zipFlag = zipFlag | ZIP_CHECKCONS;
344	    }
345	
346	    int errorFlag = 0;
347	    zipHandle = zip_open(path.c_str(), zipFlag, &errorFlag);
348	
349	    //error during opening of the file
350	    if (errorFlag!=ZIP_ER_OK) {
351	        zip_error_t error;
352	        zip_error_init_with_code(&error, errorFlag);
353	        Helper::callErrorHandlingCallback(&error, "unable to open archive: %s\n", errorHandlingCallback);
354	        zip_error_fini(&error);
355	
356	        zipHandle = nullptr;
357	        return false;
358	    }
359	
360	    if (zipHandle!=nullptr) {
361	#ifdef LIBZIPPP_WITH_ENCRYPTION
362	        if (isEncrypted()) {
363	            int result = zip_set_default_password(zipHandle, password.c_str());
364	            if (result!=0) {
365	                close();
366	                return false;
367	            }
368	        }
369	#endif
370	
371	        mode = om;
372	        return true;
373	    }
374	
375	    return false;
376	}
