378	void progress_callback(zip* /*archive*/, double progression, void* ud) {
379	    ZipArchive* za = static_cast<ZipArchive*>(ud);
380	    vector<ZipProgressListener*> listeners = za->getProgressListeners();
381	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
382	        ZipProgressListener* listener = *it;
383	        listener->progression(progression);
384	    }
385	}
386	
387	int progress_cancel_callback(zip* /*archive*/, void* ud) {
388	    ZipArchive* za = static_cast<ZipArchive*>(ud);
389	    vector<ZipProgressListener*> listeners = za->getProgressListeners();
390	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
391	        ZipProgressListener* listener = *it;
392	        if (listener->cancel())
393	          return 1;
394	    }
395	    return 0;
396	}
