398	int ZipArchive::close(void) {
399	    if (isOpen()) {
400	
401	        //do not handle zipSource at all because it will be deleted by libzip
402	        //directly when not necessary anymore
403	
404	        if (!listeners.empty()) {
405	            zip_register_progress_callback_with_state(zipHandle, progressPrecision, progress_callback, nullptr, this);
406	            zip_register_cancel_callback_with_state(zipHandle, progress_cancel_callback, nullptr, this);
407	        }
408	
409	        //avoid to reset the progress when unzipping
410	        if (mode != ReadOnly) {
411	            progress_callback(zipHandle, 0, this); //enforce the first progression call to be zero
412	        }
413	
414	        int result = zip_close(zipHandle);
415	        if (result!=0) {
416	            Helper::callErrorHandlingCallback(zipHandle, "unable to close archive: %s\n", errorHandlingCallback);
417	            return LIBZIPPP_ERROR_HANDLE_FAILURE;
418	        }
419	
420	        zipHandle = nullptr;
421	        progress_callback(zipHandle, 1, this); //enforce the last progression call to be one
422	
423	        //push back the changes in the buffer
424	        int res_code = LIBZIPPP_OK;
425	        if (bufferData!=nullptr && (mode==New || mode==Write)) {
426	            int srcOpen = zip_source_open(zipSource);
427	            if (srcOpen==0) {
428	                //IMPORTANT: the rewritten archive is read back into a *freshly allocated*
429	                //buffer. We must never read into nor realloc *bufferData here: that memory
430	                //is the storage backing the libzip source we are currently reading from.
431	                //Reusing it aliases the source and, depending on the libzip version (i.e.
432	                //whether it takes ownership of the buffer when writing), it makes
433	                //zip_source_free() release a buffer that realloc() already moved/freed,
434	                //which results in a double-free (see double_free_report / fromWritableBuffer).
435	                zip_int64_t increment = 1024;
436	                zip_int64_t capacity = bufferLength>0 ? static_cast<zip_int64_t>(bufferLength) : increment;
437	                char* outBuffer = static_cast<char*>(malloc(capacity * sizeof(char)));
438	                char* tempBuffer = outBuffer;
439	                zip_int64_t tempBufferSize = capacity;
440	                zip_int64_t totalRead = 0;
441	                zip_int64_t read = (outBuffer==nullptr) ? -1 : zip_source_read(zipSource, tempBuffer, tempBufferSize);
442	                while(read>0) {
443	                    totalRead += read;
444	                    if (totalRead>=capacity) {
445	                        zip_int64_t newCapacity = capacity + increment;
446	                        char* grownBuffer = static_cast<char*>(realloc(outBuffer, newCapacity * sizeof(char)));
447	                        if (grownBuffer==nullptr) {
448	                            Helper::callErrorHandlingCallback(zipHandle, "can't read back from source: unable to extend buffer\n", errorHandlingCallback);
449	                            ::free(outBuffer);
450	                            outBuffer = nullptr;
451	                            read = -1;
452	                            break;
453	                        }
454	                        outBuffer = grownBuffer;
455	                        capacity = newCapacity;
456	                    }
457	                    tempBuffer = outBuffer+totalRead;
458	                    tempBufferSize = capacity-totalRead;
459	                    read = zip_source_read(zipSource, tempBuffer, tempBufferSize);
460	                }
461	
462	                zip_source_close(zipSource);
463	
464	                if (outBuffer!=nullptr && read>=0) {
465	                    //freeing zipSource first guarantees libzip has released whatever it owns
466	                    //before we touch *bufferData. With freep=0 (see openBuffer) libzip never
467	                    //frees *bufferData itself, so reclaiming it here is safe and leak-free.
468	                    zip_source_free(zipSource);
469	                    zipSource = nullptr;
470	
471	                    ::free(*bufferData);
472	                    *bufferData = outBuffer;
473	                    bufferLength = totalRead;
474	                } else {
475	                    Helper::callErrorHandlingCallback(zipHandle, "can't read back from source: changes were not pushed in the buffer\n", errorHandlingCallback);
476	                    res_code = LIBZIPPP_ERROR_HANDLE_FAILURE;
477	                    if (outBuffer!=nullptr) { ::free(outBuffer); }
478	                    zip_source_free(zipSource);
479	                    zipSource = nullptr;
480	                }
481	            } else {
482	                Helper::callErrorHandlingCallback((zip*)nullptr, "can't read back from source: changes were not pushed in the buffer\n", errorHandlingCallback);
483	                res_code = LIBZIPPP_ERROR_HANDLE_FAILURE;
484	
485	                zip_source_free(zipSource);
486	                zipSource = nullptr;
487	            }
488	        }
489	
490	        mode = NotOpen;
491	        return res_code;
492	    }
493	
494	    return LIBZIPPP_OK;
495	}
