497	void ZipArchive::discard(void) {
498	    if (isOpen()) {
499	        zip_discard(zipHandle);
500	        zipHandle = nullptr;
501	
502	        if (bufferData!=nullptr && (mode==New || mode==Write)) {
503	            zip_source_free(zipSource);
504	            zipSource = nullptr;
505	        }
506	
507	        mode = NotOpen;
508	    }
509	}
