540	bool ZipArchive::setEntryCompressionConfig(ZipEntry& entry, CompressionMethod comp, libzippp_uint32 level) const {
541	    if (!isOpen()) { return false; }
542	    if (entry.zipFile!=this) { return false; }
543	    if (mode==ReadOnly) { return false; }
544	    const libzippp_uint16 comp_libzip = convertCompressionToLibzip(comp);
545	
546	    bool success = zip_set_file_compression(zipHandle, entry.index, comp_libzip, level)==0;
547	    if (success) {
548	        entry.compressionMethod = comp_libzip;
549	        entry.compressionLevel = level;
550	    }
551	    return success;
552	}
