583	ZipEntry ZipArchive::resolveEntry(const ZipEntry& zipEntry, State state, libzippp_uint64* outSize) const {
584	    if (outSize!=nullptr) { *outSize = 0; }
585	
586	    //a null-ZipEntry (e.g. obtained through getEntry in a state where the name does not
587	    //exist) cannot be resolved in any state
588	    if (zipEntry.isNull()) { return ZipEntry(); }
589	
590	    int flag = stateFlags(state);
591	    struct zip_stat stat;
592	    zip_stat_init(&stat);
593	
594	    //stat the (stable) slot in the requested state: this fails for an entry deleted in the
595	    //current state (read with Current) or a newly added entry (read with Original)
596	    if (zip_stat_index(zipHandle, zipEntry.getIndex(), flag, &stat)!=0) { return ZipEntry(); }
597	
598	    ZipEntry resolved = createEntry(&stat);
599	    if (outSize!=nullptr) { *outSize = stat.size; }
600	    return resolved;
601	}
602	
603	vector<ZipEntry> ZipArchive::getEntries(State state) const {
604	    if (!isOpen()) { return vector<ZipEntry>(); }
605	
606	    struct zip_stat stat;
607	    zip_stat_init(&stat);
608	
609	    vector<ZipEntry> entries;
610	    int flag = state==Original ? LIBZIPPP_ORIGINAL_STATE_FLAGS : ZIP_FL_ENC_GUESS;
611	    libzippp_int64 nbEntries = getNbEntries(state);
612	    for(libzippp_int64 i=0 ; i<nbEntries ; ++i) {
613	        int result = zip_stat_index(zipHandle, i, flag, &stat);
614	        if (result==0) {
615	            ZipEntry entry = createEntry(&stat);
616	            entries.push_back(entry);
617	        } else {
618	            //TODO handle read error => crash ?
619	        }
620	    }
621	    return entries;
622	}
