624	bool ZipArchive::hasEntry(const string& name, bool excludeDirectories, bool caseSensitive, State state) const {
625	    if (!isOpen()) { return false; }
626	
627	    int flags = 0;
628	    if (excludeDirectories) { flags = flags | ZIP_FL_NODIR; }
629	    if (!caseSensitive) { flags = flags | ZIP_FL_NOCASE; }
630	    if (state==Original) { flags = flags | LIBZIPPP_ORIGINAL_STATE_FLAGS; }
631	    else { flags = flags | ZIP_FL_ENC_GUESS; }
632	
633	    libzippp_int64 index = zip_name_locate(zipHandle, name.c_str(), flags);
634	    return index>=0;
635	}
636	
637	ZipEntry ZipArchive::getEntry(const string& name, bool excludeDirectories, bool caseSensitive, State state) const {
638	    if (isOpen()) {
639	        int flags = 0;
640	        if (excludeDirectories) { flags = flags | ZIP_FL_NODIR; }
641	        if (!caseSensitive) { flags = flags | ZIP_FL_NOCASE; }
642	        if (state==Original) { flags = flags | LIBZIPPP_ORIGINAL_STATE_FLAGS; }
643	        else { flags = flags | ZIP_FL_ENC_GUESS; }
644	
645	        libzippp_int64 index = zip_name_locate(zipHandle, name.c_str(), flags);
646	        if (index>=0) {
647	            //the located index must be stat'd in the SAME state: locating a renamed entry
648	            //in the original state gives the original slot, whose name and size are the
649	            //original ones (using the current stat here would return the new name/length)
650	            return getEntry(index, state);
651	        } else {
652	            //name not found in the requested state
653	        }
654	    }
655	    return ZipEntry();
656	}
