695	void* ZipArchive::readEntry(const ZipEntry& zipEntry, bool asText, State state, libzippp_uint64 size) const {
696	    if (!isOpen()) { return nullptr; }
697	    if (zipEntry.zipFile!=this) { return nullptr; }
698	
699	    //resolve the entry in the requested state: the uncompressed size and the existence of
700	    //the entry depend on the state (a replacement may be longer, shorter or empty, a deleted
701	    //entry is only readable as Original and a newly added one only as Current)
702	    libzippp_uint64 entrySize = 0;
703	    ZipEntry resolved = resolveEntry(zipEntry, state, &entrySize);
704	    if (resolved.isNull()) { return nullptr; }
705	
706	    int flag = stateFlags(state);
707	    struct zip_file* zipFile = zip_fopen_index(zipHandle, resolved.getIndex(), flag);
708	    if (zipFile) {
709	        //zero means "read the whole content" and a too big length returns all of it; the
710	        //captured zipEntry size is intentionally never used to bound the read
711	        libzippp_uint64 uisize = size==0 || size>entrySize ? entrySize : size;
712	
713	        char* data = NEW_CHAR_ARRAY(uisize+(asText ? 1 : 0))
714	        if (!data) { //allocation error
715	            zip_fclose(zipFile);
716	            return nullptr;
717	        }
718	
719	        libzippp_int64 result = zip_fread(zipFile, data, uisize);
720	        zip_fclose(zipFile);
721	
722	        //avoid buffer copy
723	        if (asText) { data[uisize] = '\0'; }
724	
725	        libzippp_int64 isize = (libzippp_int64)uisize;
726	        if (result==isize) {
727	            return data;
728	        } else { //unexpected number of bytes read => crash ?
729	            delete[] data;
730	        }
731	    } else {
732	        //unable to read the entry (e.g. it does not exist in the requested state) => crash ?
733	    }
734	
735	    return nullptr;
736	}
737	
738	void* ZipArchive::readEntry(const string& zipEntry, bool asText, State state, libzippp_uint64 size) const {
739	    //the name is interpreted in the requested state: there is no fallback to the other state
740	    //if the name does not exist in this one
741	    ZipEntry entry = getEntry(zipEntry, false, true, state);
742	    if (entry.isNull()) { return nullptr; }
743	    return readEntry(entry, asText, state, size);
744	}
