959	bool ZipArchive::addFile(const string& entryName, const string& file) const {
960	    if (!isOpen()) { return false; }
961	    if (mode==ReadOnly) { return false; } //adding not allowed
962	    if (LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
963	
964	    string::size_type lastSlash = entryName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR);
965	    if (lastSlash!=string::npos) { //creates the needed parent directories
966	        string dirEntry = entryName.substr(0, lastSlash+1);
967	        bool dadded = addEntry(dirEntry);
968	        if (!dadded) { return false; }
969	    }
970	
971	    const char* filepath = file.c_str();
972	    zip_source* source = zip_source_file(zipHandle, filepath, 0, -1);
973	    if (source!=nullptr) {
974	        libzippp_int64 result = zip_file_add(zipHandle, entryName.c_str(), source, ZIP_FL_OVERWRITE);
975	        if (result>=0) {
976	            zip_file_set_mtime(zipHandle, result, time(nullptr), 0);
977	            if (useArchiveCompressionMethod) {
978	              zip_set_file_compression(zipHandle, result, compressionMethod, 0);
979	            }
980	#ifdef LIBZIPPP_WITH_ENCRYPTION
981	            if (isEncrypted()) {
982	                if (zip_file_set_encryption(zipHandle,result,encryptionMethod,nullptr)!=0) { //unable to encrypt
983	                    zip_source_free(source);
984	                } else {
985	                    return true;
986	                }
987	            } else {
988	                return true;
989	            }
990	#else
991	            return true;
992	#endif
993	        } else {
994	            //unable to add the file
995	            zip_source_free(source);
996	        }
997	    } else {
998	        //unable to create the zip_source
999	    }
1000	    return false;
1001	}
