1003	bool ZipArchive::addData(const string& entryName, const void* data, libzippp_uint64 length, bool freeData) const {
1004	    if (!isOpen()) { return false; }
1005	    if (mode==ReadOnly) { return false; } //adding not allowed
1006	    if (LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1007	
