57	        assert(zip_dir_add(zh, name.c_str(), 0) >= 0);
58	    } else {
59	        zip_source_t* source = zip_source_buffer(zh, content, strlen(content), 0);
60	        assert(source != nullptr);
61	        assert(zip_file_add(zh, name.c_str(), source, 0) >= 0);
62	    }
63	}
