1084	/*
1085	 * Atomic directory rename: a destination occupied by an entry that does not participate in
1086	 * the move must make renameEntry fail with LIBZIPPP_ERROR_UNKNOWN. The conflict check uses
1087	 * the current uncommitted state and must not be limited to the existence of the destination
1088	 * directory entry itself: here new/target/last.txt exists while there is no explicit new/ or
1089	 * new/target/ directory entry. On failure no entry is moved and no directory is created,
1090	 * even after closing and reopening the archive.
1091	 */
1092	void test26() {
1093	    cout << "Running test 26...";
1094	
1095	    {
1096	        //build the archive directly with libzip so that new/ and new/target/ stay implicit
1097	        int err = 0;
1098	        zip* zh = zip_open("test.zip", ZIP_CREATE|ZIP_TRUNCATE, &err);
1099	        assert(zh != nullptr);
1100	        addRawEntry(zh, "src/", "");
1101	        addRawEntry(zh, "src/first.txt", "FIRST");
1102	        addRawEntry(zh, "src/last.txt", "LAST");
1103	        addRawEntry(zh, "new/target/last.txt", "TARGET");
1104	        assert(zip_close(zh) == 0);
1105	    }
1106	
1107	    ZipArchive z("test.zip");
1108	    z.open(ZipArchive::Write);
1109	    assert(z.getNbEntries() == 4); //no explicit new/ nor new/target/
1110	    assert(!z.hasEntry("new/"));
1111	    assert(!z.hasEntry("new/target/"));
1112	
1113	    assert(z.renameEntry("src/", "new/target/") == LIBZIPPP_ERROR_UNKNOWN);
1114	
1115	    //the moved entries kept their original names and contents
1116	    assert(z.hasEntry("src/"));
1117	    assert(z.hasEntry("src/first.txt"));
1118	    assert(z.hasEntry("src/last.txt"));
1119	    assert(z.getEntry("src/first.txt").readAsText() == "FIRST");
1120	    assert(z.getEntry("src/last.txt").readAsText() == "LAST");
1121	    //the conflicting entry is untouched
1122	    assert(z.hasEntry("new/target/last.txt"));
1123	    assert(z.getEntry("new/target/last.txt").readAsText() == "TARGET");
1124	    //no parent directory was created by the failed call
1125	    assert(!z.hasEntry("new/"));
1126	    assert(!z.hasEntry("new/target/"));
1127	    assert(z.close() == LIBZIPPP_OK);
1128	
1129	    //the failure left no trace on disk either
1130	    ZipArchive r("test.zip");
1131	    r.open(ZipArchive::ReadOnly);
1132	    assert(r.getNbEntries() == 4);
1133	    assert(r.hasEntry("src/") && r.hasEntry("src/first.txt") && r.hasEntry("src/last.txt"));
1134	    assert(r.hasEntry("new/target/last.txt"));
1135	    assert(!r.hasEntry("new/") && !r.hasEntry("new/target/"));
1136	    r.close();
1137	    r.unlink();
1138	
1139	    cout << " done." << endl;
1140	}
