1142	/*
1143	 * A failed directory rename must roll back to the archive state just before the call (not
1144	 * the state at opening time): previously added entries, replaced contents, modified
1145	 * comments and deletions all survive. The archive stays open and usable, so the rename can
1146	 * be retried with a conflict-free name; everything is then visible after a close/reopen.
1147	 */
1148	void test27() {
1149	    cout << "Running test 27...";
1150	
1151	    {
1152	        int err = 0;
1153	        zip* zh = zip_open("test.zip", ZIP_CREATE|ZIP_TRUNCATE, &err);
1154	        assert(zh != nullptr);
1155	        addRawEntry(zh, "src/", "");
1156	        addRawEntry(zh, "src/first.txt", "FIRST");
1157	        addRawEntry(zh, "src/last.txt", "LAST");
1158	        addRawEntry(zh, "new/target/last.txt", "TARGET");
1159	        addRawEntry(zh, "victim.txt", "V");
1160	        assert(zip_close(zh) == 0);
1161	    }
1162	
1163	    ZipArchive z("test.zip");
1164	    z.open(ZipArchive::Write);
1165	
1166	    //pending modifications performed before the failing rename
1167	    assert(z.addData("added.txt", "A", 1));
1168	    assert(z.addData("src/first.txt", "REPLACED", 8));
1169	    assert(z.getEntry("src/last.txt").setComment("last-comment"));
1170	    assert(z.deleteEntry("victim.txt") == 1);
1171	
1172	    assert(z.renameEntry("src/", "new/target/") == LIBZIPPP_ERROR_UNKNOWN);
1173	
1174	    //the prior uncommitted modifications are all still there
1175	    assert(z.hasEntry("added.txt"));
1176	    assert(z.getEntry("src/first.txt").readAsText() == "REPLACED");
1177	    assert(z.getEntry("src/last.txt").getComment() == "last-comment");
1178	    assert(!z.hasEntry("victim.txt"));
1179	    //and the failed move left no trace
1180	    assert(z.hasEntry("src/") && z.hasEntry("src/first.txt") && z.hasEntry("src/last.txt"));
1181	    assert(!z.hasEntry("new/") && !z.hasEntry("new/target/"));
1182	
1183	    //retry with a free name while the archive is still open
1184	    assert(z.renameEntry("src/", "moved/") == 3);
1185	    assert(z.hasEntry("moved/") && z.hasEntry("moved/first.txt") && z.hasEntry("moved/last.txt"));
1186	    assert(!z.hasEntry("src/"));
