1188	    assert(z.getEntry("moved/last.txt").getComment() == "last-comment");
1189	    assert(z.close() == LIBZIPPP_OK);
1190	
1191	    ZipArchive r("test.zip");
1192	    r.open(ZipArchive::ReadOnly);
