1196	    assert(r.getEntry("moved/first.txt").readAsText() == "REPLACED");
1197	    assert(r.getEntry("moved/last.txt").getComment() == "last-comment");
1198	    assert(r.getEntry("new/target/last.txt").readAsText() == "TARGET");
1199	    assert(!r.hasEntry("victim.txt"));
1200	    r.close();
1201	    r.unlink();
1202	
1203	    cout << " done." << endl;
