1206	/*
1207	 * Moving a directory below its own path is supported. Entries that participate in the move
1208	 * and free their original name must not be considered destination conflicts. Moving a/, a/b/
1209	 * and a/b/file.bin to a/b/ yields a/, a/b/, a/b/b/ and a/b/b/file.bin (the re-created a/
1210	 * parent is not counted), and the returned value is the number of renamed pre-existing
1211	 * entries (3).
1212	 */
1213	void test28() {
1214	    cout << "Running test 28...";
1215	
1216	    {
