1244	    r.close();
1245	    r.unlink();
1246	
1247	    cout << " done." << endl;
1248	}
1249	
1250	/*
1251	 * Miscellaneous directory rename rules:
1252	 * - an empty directory obeys the same success/failure rules,
1253	 * - the trailing '/' is appended to the destination when missing,
1254	 * - entries with a similar but non-descendant name are not moved,
1255	 * - missing parent directories are created (but not counted),
1256	 * - file content, relative paths and entry comments follow the entries.
1257	 */
1258	void test29() {
1259	    cout << "Running test 29...";
1260	
1261	    {
1262	        int err = 0;
