1278	    assert(ze.hasEntry("renamed-empty/"));
1279	    assert(!ze.hasEntry("empty/"));
1280	    ze.close();
1281	    ze.unlink();
1282	
1283	    //similar names, parent creation, content and comment preservation
1284	    {
1285	        int err = 0;
1286	        zip* zh = zip_open("test.zip", ZIP_CREATE|ZIP_TRUNCATE, &err);
1287	        assert(zh != nullptr);
1288	        addRawEntry(zh, "d/", "");
