}

void test9() {
    cout << "Running test 9...";

    const char* txtFile = "this is some data";
    int len = strlen(txtFile);

    ZipArchive z1("test.zip");
    z1.open(ZipArchive::Write);
    z1.addData("somedata/in/subfolders/test.txt", txtFile, len);
