// Verification of the ZipEntry session-lifetime rules (not part of tests.cpp).
#include <assert.h>
#include <string.h>
#include <iostream>
#include <sstream>
#include <string>

#include "libzippp.h"

using namespace std;
using namespace libzippp;

class CancelListener : public ZipProgressListener {
public:
    CancelListener(void) : doCancel(false) {}
    bool doCancel;
    void progression(double) {}
    int cancel() { return doCancel ? 1 : 0; }
};

static void makeArchive() {
    ZipArchive z("sess.zip");
    z.open(ZipArchive::New);
    z.addData("a.txt", "AAAA", 4);
    z.addData("dir/b.txt", "BBBB", 4);
    assert(z.close() == LIBZIPPP_OK);
}

int main() {
    makeArchive();

    // --- 1. entries die with close(); metadata stays queryable; isNull unchanged ---
    {
        ZipArchive z("sess.zip");
        z.open(ZipArchive::ReadOnly);
        ZipEntry e = z.getEntry("a.txt");
        ZipEntry copy = e;
        ZipEntry assigned;
        assigned = e;
        assert(!e.isNull());
        assert(e.readAsText() == "AAAA");
        assert(z.close() == LIBZIPPP_OK);

        assert(!e.isNull()); //expiry does not change isNull
        assert(e.getName() == "a.txt");
        assert(e.getSize() == 4);
        assert(e.readAsText().empty());
        assert(e.readAsBinaryString().empty());
        assert(e.readAsBinary() == nullptr);
        assert(e.getComment().empty());
        assert(!e.setComment("x"));
        assert(!e.setCompressionMethod(DEFLATE));
        assert(!e.setCompressionLevel(3));
        //copies/assignments share the same (now expired) session
        assert(copy.readAsText().empty());
        assert(assigned.readAsText().empty());

        ostringstream oss;
        assert(e.readContent(oss) == LIBZIPPP_ERROR_NOT_OPEN);
        assert(oss.str().empty()); //rejected read wrote nothing

        //archive-level entry points reject the stale entry
        assert(z.readEntry(e, oss) == LIBZIPPP_ERROR_NOT_OPEN); //archive not open
        assert(z.deleteEntry(e) == LIBZIPPP_ERROR_NOT_OPEN);
        assert(z.renameEntry(e, "c.txt") == LIBZIPPP_ERROR_NOT_OPEN);
        assert(z.readEntry(e, true) == nullptr);
        assert(z.getEntryComment(e).empty());
        assert(!z.setEntryComment(e, "x"));
        ZipEntry me = e;
        assert(!z.setEntryCompressionConfig(me, DEFLATE, 0));

        // --- 2. reopening the same ZipArchive object does not revive old entries ---
        z.open(ZipArchive::Write);
        ZipEntry fresh = z.getEntry("a.txt");
        assert(!fresh.isNull());
        assert(fresh.getIndex() == e.getIndex()); //same slot, same name
        assert(fresh.readAsText() == "AAAA");
        //old entry (and its copies) stay dead and cannot touch the new session
        assert(e.readAsText().empty());
        assert(!e.setComment("hacked"));
        assert(fresh.getComment().empty());
        ostringstream oss2;
        assert(e.readContent(oss2) == LIBZIPPP_ERROR_NOT_OPEN);
        assert(oss2.str().empty());
        assert(z.readEntry(e, oss2) == LIBZIPPP_ERROR_INVALID_ENTRY);
        assert(z.deleteEntry(e) == LIBZIPPP_ERROR_INVALID_ENTRY);
        assert(z.renameEntry(e, "c.txt") == LIBZIPPP_ERROR_INVALID_ENTRY);
        assert(z.readEntry(e, true) == nullptr);
        assert(z.getEntryComment(e).empty());
        assert(!z.setEntryComment(e, "hacked"));
        assert(!z.setEntryCompressionConfig(me, DEFLATE, 0));
        assert(fresh.getComment().empty()); //untouched

        //repeated open with the same mode keeps the session (and entries) alive
        assert(z.open(ZipArchive::Write));
        assert(fresh.readAsText() == "AAAA");
        assert(fresh.setComment("c1"));
        assert(fresh.getComment() == "c1");

        // --- 3. discard kills the entries too ---
        ZipEntry d = z.getEntry("dir/b.txt");
        assert(d.readAsText() == "BBBB");
        z.discard();
        assert(d.readAsText().empty());
        assert(!d.setComment("x"));
        ostringstream oss3;
        assert(d.readContent(oss3) == LIBZIPPP_ERROR_NOT_OPEN);
        z.unlink();
    }

    // --- 4. null entries are safe to use ---
    {
        ZipEntry null1;
        ZipArchive z("sess.zip");
        z.open(ZipArchive::ReadOnly);
        ZipEntry null2 = z.getEntry("no/such/entry");
        assert(null1.isNull() && null2.isNull());
        ZipEntry nulls[2] = { null1, null2 };
        for (int i = 0; i < 2; ++i) {
            ZipEntry& n = nulls[i];
            assert(n.readAsText().empty());
            assert(n.readAsBinaryString().empty());
            assert(n.readAsBinary() == nullptr);
            assert(n.getComment().empty());
            assert(!n.setComment("x"));
            assert(!n.setCompressionMethod(DEFLATE));
            assert(!n.setCompressionLevel(1));
            ostringstream oss;
            assert(n.readContent(oss) == LIBZIPPP_ERROR_INVALID_ENTRY);
            assert(oss.str().empty());
        }
        //archive-level with null entry while open
        ostringstream oss;
        assert(z.readEntry(null1, oss) == LIBZIPPP_ERROR_INVALID_ENTRY);
        assert(oss.str().empty());
        assert(z.deleteEntry(null1) == LIBZIPPP_ERROR_INVALID_ENTRY);
        assert(z.renameEntry(null1, "x") == LIBZIPPP_ERROR_INVALID_ENTRY);
        assert(z.readEntry(null1, true) == nullptr);
        assert(z.getEntryComment(null1).empty());
        assert(!z.setEntryComment(null1, "x"));
        assert(!z.setEntryCompressionConfig(null1, DEFLATE, 0));
        z.close();
        z.unlink();
    }

    // --- 5. entries from another archive are rejected ---
    {
        makeArchive();
        ZipArchive z1("sess.zip");
        ZipArchive z2("sess.zip");
        z1.open(ZipArchive::Write);
        z2.open(ZipArchive::Write);
        ZipEntry foreign = z2.getEntry("a.txt");
        assert(!foreign.isNull());
        ostringstream oss;
        assert(z1.readEntry(foreign, oss) == LIBZIPPP_ERROR_INVALID_ENTRY);
        assert(oss.str().empty());
        assert(z1.deleteEntry(foreign) == LIBZIPPP_ERROR_INVALID_ENTRY);
        assert(z1.renameEntry(foreign, "z.txt") == LIBZIPPP_ERROR_INVALID_ENTRY);
        assert(z1.readEntry(foreign, true) == nullptr);
        assert(z1.getEntryComment(foreign).empty());
        assert(!z1.setEntryComment(foreign, "x"));
        assert(!z1.setEntryCompressionConfig(foreign, DEFLATE, 0));
        //the foreign entry still works on its own archive
        assert(foreign.readAsText() == "AAAA");
        z1.discard();
        z2.discard();
        z1.unlink();
    }

    // --- 6. entries die when the archive object is destroyed / freed ---
    {
        ZipEntry survivor;
        {
            ZipArchive z("sess2.zip");
            z.open(ZipArchive::New);
            z.addData("x.txt", "XYZ", 3);
            survivor = z.getEntry("x.txt");
            assert(survivor.readAsText() == "XYZ");
        } //destructor commits and closes
        assert(!survivor.isNull());
        assert(survivor.getName() == "x.txt");
        assert(survivor.readAsText().empty());
        assert(survivor.readAsBinary() == nullptr);
        assert(!survivor.setComment("x"));
        ostringstream oss;
        assert(survivor.readContent(oss) == LIBZIPPP_ERROR_NOT_OPEN);

        ZipArchive* heap = new ZipArchive("sess2.zip");
        heap->open(ZipArchive::ReadOnly);
        ZipEntry he = heap->getEntry("x.txt");
        assert(he.readAsText() == "XYZ");
        ZipArchive::free(heap);
        assert(he.readAsText().empty());
        assert(he.readAsBinary() == nullptr);
        ostringstream oss2;
        assert(he.readContent(oss2) == LIBZIPPP_ERROR_NOT_OPEN);

        ZipArchive del("sess2.zip");
        del.open(ZipArchive::ReadOnly);
        del.close();
        del.unlink();
    }

    // --- 7. cancelled commit keeps the session alive; discard ends it ---
    {
        ZipArchive z("sess.zip");
        z.open(ZipArchive::Write);
        z.addData("big.txt", string(100000, 'z').data(), 100000);
        ZipEntry e = z.getEntry("big.txt");
        assert(!e.isNull());
        CancelListener cl;
        cl.doCancel = true;
        z.addProgressListener(&cl);
        int rc = z.close();
        assert(rc != LIBZIPPP_OK);
        assert(z.isOpen()); //commit cancelled: still open
        //entries remain usable: read, modify, retry
        assert(e.readAsText().size() == 100000);
        assert(e.setComment("still-alive"));
        assert(e.getComment() == "still-alive");
        cl.doCancel = false;
        assert(z.close() == LIBZIPPP_OK);
        assert(!z.isOpen());
        //now the session is over
        assert(e.readAsText().empty());
        assert(!e.setComment("dead"));

        ZipArchive r("sess.zip");
        r.open(ZipArchive::ReadOnly);
        assert(r.getEntry("big.txt").getComment() == "still-alive");
        r.close();
        r.unlink();
    }

    // --- 8. buffer-based archives follow the same rules ---
    {
        void* buffer = calloc(4096, 1);
        ZipArchive* z = ZipArchive::fromWritableBuffer(&buffer, 4096, ZipArchive::New);
        assert(z != nullptr);
        z->addData("mem.txt", "MEM", 3);
        ZipEntry e = z->getEntry("mem.txt");
        assert(e.readAsText() == "MEM");
        assert(z->close() == LIBZIPPP_OK);
        libzippp_uint32 len = (libzippp_uint32)z->getBufferLength();
        //closed: entry is dead
        assert(e.readAsText().empty());
        ostringstream oss;
        assert(e.readContent(oss) == LIBZIPPP_ERROR_NOT_OPEN);
        ZipArchive::free(z);
        assert(e.readAsText().empty());

        ZipArchive* z2 = ZipArchive::fromBuffer(buffer, len);
        assert(z2 != nullptr);
        ZipEntry e2 = z2->getEntry("mem.txt");
        assert(e2.readAsText() == "MEM");
        ZipArchive::free(z2); //destruction invalidates
        assert(e2.readAsText().empty());
        assert(e2.readAsBinary() == nullptr);
        free(buffer);
    }

    // --- 9. retained copies do not prevent commit/discard/release ---
    {
        ZipEntry kept;
        ZipArchive z("sess.zip");
        z.open(ZipArchive::Write);
        z.addData("k.txt", "K", 1);
        kept = z.getEntry("k.txt");
        assert(z.close() == LIBZIPPP_OK); //commit works with a live copy around
        ZipArchive r("sess.zip");
        r.open(ZipArchive::ReadOnly);
        assert(r.hasEntry("k.txt"));
        r.close();
        r.unlink();
        assert(kept.readAsText().empty());
    }

    cout << "all session-lifetime checks passed." << endl;
    return 0;
}

